<?php require 'config.php';require_login();$title='Medicine inventory';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(isset($_POST['delete'])){$pdo->prepare('DELETE FROM medicines WHERE id=?')->execute([(int)$_POST['delete']]);flash('Medicine removed.');go('medicines.php');}
try{$pdo->prepare('INSERT INTO medicines(name,category,batch_no,expiry_date,quantity,reorder_level,price) VALUES(?,?,?,?,?,?,?)')->execute([trim($_POST['name']),trim($_POST['category']),trim($_POST['batch_no']),$_POST['expiry_date'],(int)$_POST['quantity'],(int)$_POST['reorder_level'],(float)$_POST['price']]);flash('Medicine added to inventory.');}catch(PDOException $e){flash('Could not add medicine. Check that the batch number is unique.','error');}go('medicines.php');}
$rows=$pdo->query('SELECT * FROM medicines ORDER BY name')->fetchAll();require 'partials/header.php';?>
<div class="pagehead"><div><div class="eyebrow">INVENTORY</div><h1>Medicine inventory</h1><p class="sub">Manage product details, batches, expiry dates and available stock.</p></div></div>
<div class="card"><h2>Add medicine</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="formgrid" style="margin-top:15px"><div class="field"><label>Medicine name</label><input name="name" required placeholder="e.g. Paracetamol 500mg"></div><div class="field"><label>Category</label><input name="category" required placeholder="e.g. Tablet, Syrup"></div><div class="field"><label>Batch number</label><input name="batch_no" required></div><div class="field"><label>Expiry date</label><input type="date" name="expiry_date" required></div><div class="field"><label>Quantity in stock</label><input type="number" min="0" name="quantity" required></div><div class="field"><label>Reorder level</label><input type="number" min="0" name="reorder_level" value="10" required></div><div class="field"><label>Unit price (₹)</label><input type="number" min="0" step=".01" name="price" required></div></div><div class="actions"><button class="btn">＋ Add to inventory</button></div></form></div>
<div class="card"><div class="cardhead"><h2>All medicines <span class="muted">(<?=count($rows)?>)</span></h2></div><div class="tablewrap"><table><thead><tr><th>Medicine</th><th>Category</th><th>Batch</th><th>Expiry</th><th>Stock</th><th>Price</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $m):$expired=$m['expiry_date']<date('Y-m-d');$low=$m['quantity']<=$m['reorder_level'];?><tr><td><strong><?=h($m['name'])?></strong></td><td><?=h($m['category'])?></td><td><?=h($m['batch_no'])?></td><td><?=h($m['expiry_date'])?></td><td><?=$m['quantity']?></td><td>₹<?=number_format((float)$m['price'],2)?></td><td><span class="badge <?=($expired?'red':($low?'warn':''))?>"><?=$expired?'Expired':($low?'Low stock':'In stock')?></span></td><td><form method="post" onsubmit="return confirm('Delete this medicine?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button class="btn danger small" name="delete" value="<?=$m['id']?>">Delete</button></form></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="8" class="empty">No medicines added yet.</td></tr><?php endif?></tbody></table></div></div><?php require 'partials/footer.php';?>
